function getGamePrice(game) {
  const price = gamePrices[game.id];
  return typeof price === "number" ? price : null;
}

function formatGamePrice(game) {
  const price = getGamePrice(game);

  if (price === null) {
    return "Price TBD";
  }

  if (price === 0) {
    return "Free";
  }

  return `₩${price.toLocaleString("en-US")}`;
}

